INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-notch', 'east', 'the-gully-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bealach', 'east', 'the-pass-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shoulder', 'east', 'the-sun-shoulder', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-crag', 'east', 'the-brink', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-brink', 'door', 'The Brink', 'A ledge on the face of the first crag, reached by the one line of holds that goes anywhere, with the whole foot of the mountain laid out underneath and nothing between you and it. It is not a way anything with four legs can come. That is the entire reason it is worth knowing about: everything else on this hill uses the notch or the pass, and nothing at all uses this.', 0, 0, 'mountain', 0, 79, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brink', 'east', 'the-corrie-lip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brink', 'west', 'the-first-crag', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gully-head', 'door', 'The Gully Head', 'You come out of the notch and the ground opens without warning into a bowl a half-mile across, walled on three sides, with the floor of it well below you and a black lochan sitting in the middle. It is the first thing on this mountain that has a shape. Everything below was slope; this was made, by something, on purpose, and then abandoned.', 0, 0, 'mountain', 0, 80, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-head', 'north', 'the-corrie-lip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-head', 'south', 'the-fallen-block', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-head', 'east', 'the-corrie-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-head', 'west', 'the-notch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-corrie-mouth', 'door', 'The Corrie Mouth', 'The lip of the bowl, where the ground stops falling away and starts falling in. Grass runs right to the edge and then there is nothing under it. From here you can see the whole floor at once, and how much of it is water, and how little of it is anywhere you could stand.', 0, 0, 'mountain', 0, 81, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-mouth', 'north', 'the-black-scree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-mouth', 'south', 'the-corrie-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-mouth', 'east', 'the-lochan', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-mouth', 'west', 'the-gully-head', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lochan', 'door', 'The Lochan', 'Black water, perfectly still, and so dark that the reflection of the back wall in it is better lit than the wall itself. It has no inflow you can find and one thin outflow at the far end. Nothing rises in it. Nothing rises in water this cold and this deep and this poor.', 0, 0, 'mountain', 0, 82, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan', 'north', 'the-drift-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan', 'south', 'the-lochan-shore', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan', 'east', 'the-back-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan', 'west', 'the-corrie-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lochan-shore', 'door', 'The Lochan Shore', 'A strand of grey grit round the water''s edge, wide in places and nothing at all in others, with the wall going straight up out of it further round. There are tracks in the grit — deer, and something with pads, and the pads are following the deer.', 0, 0, 'mountain', 0, 82, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan-shore', 'north', 'the-lochan', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan-shore', 'east', 'the-water-lip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan-shore', 'west', 'the-corrie-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-back-wall', 'door', 'The Back Wall', 'The head wall of the corrie, seven hundred feet of wet black rock leaning very slightly over you, streaked white where water comes down it and green-black where it does not. Looking up it for any length of time is unpleasant in a way that has nothing to do with the height. There is no way up this.', 0, 0, 'mountain', 0, 83, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-wall', 'north', 'the-old-snow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-wall', 'south', 'the-water-lip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-wall', 'east', 'the-hanging-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-wall', 'west', 'the-lochan', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-corrie-floor', 'door', 'The Corrie Floor', 'Flat ground, or nearly, floored with everything the walls have shed and gone over with moss between the blocks. It is out of the wind entirely — the first still air since the shore — and the quiet in here is total and takes some getting used to.', 0, 0, 'mountain', 0, 81, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-floor', 'north', 'the-corrie-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-floor', 'east', 'the-lochan-shore', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-floor', 'west', 'the-fallen-block', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drift-edge', 'door', 'The Drift Edge', 'The old snow ends here in a wall waist high, undercut and blue in the shadow of its own overhang, with a foot of bare stony ground between it and the grass. That gap is where the drift used to be a month ago. It has been the same gap for longer than a month.', 0, 0, 'mountain', 0, 82, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-edge', 'south', 'the-lochan', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-edge', 'east', 'the-old-snow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-edge', 'west', 'the-black-scree', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-snow', 'door', 'The Old Snow', 'Snow that has been here through at least one summer, packed to something between ice and stone, grey on top with a season''s grit and dead insects. It rings under a boot heel. Whatever fell into this is still in it, at whatever depth the year it fell put it.', 0, 0, 'mountain', 0, 83, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-snow', 'south', 'the-back-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-snow', 'east', 'the-upper-drift', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-snow', 'west', 'the-drift-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-black-scree', 'door', 'The Black Scree', 'Scree the colour of coal, small and sharp and endlessly loose, running from the corrie rim down to the floor in one unbroken sheet. Nothing has ever grown on it and nothing will; there is no ground in it, only pieces. It moves under you and keeps moving after you stop.', 0, 0, 'mountain', 0, 81, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-scree', 'south', 'the-corrie-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-scree', 'east', 'the-drift-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-scree', 'west', 'the-corrie-lip', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fallen-block', 'door', 'The Fallen Block', 'A slab the size of a barn came off the wall at some point and landed on its edge, and it has stood that way ever since with a wedge of dry ground under its lean. You can get right in under it. It is out of the wind, out of the wet, out of the sight of anything above, and it is the only such place in this bowl.', 0, 1, 'mountain', 0, 80, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-block', 'north', 'the-gully-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-block', 'east', 'the-corrie-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-corrie-lip', 'door', 'The Corrie Lip', 'The rim, on the north side, where the ground rolls over and goes. Standing on it you have the bowl on one hand and the whole open shoulder on the other, and the wind that has been absent down in the corrie is suddenly back and hard. Everything crossing between the two goes over this line.', 0, 0, 'mountain', 0, 80, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-lip', 'north', 'the-corrie-rim', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-lip', 'south', 'the-gully-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-lip', 'east', 'the-black-scree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-lip', 'west', 'the-brink', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-water-lip', 'door', 'The Water Lip', 'The one place the lochan lets anything out: a notch in the rock a yard wide with the water going over it flat and silent and then falling out of sight. There is no noise from it at all until you look over, and then there is, a long way down.', 0, 0, 'mountain', 0, 83, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-lip', 'north', 'the-back-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-lip', 'west', 'the-lochan-shore', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hanging-step', 'door', 'The Hanging Step', 'A shelf running out from the corner of the back wall, wide enough to walk and narrowing as it goes, carrying you out onto the face above the drop. It is the way out of the bowl that is not the way you came in. It does not feel like one for the first hundred yards.', 0, 0, 'mountain', 0, 84, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-step', 'south', 'the-lower-band', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-step', 'west', 'the-back-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-corrie-rim', 'door', 'The Corrie Rim', 'The very edge of the bowl, a knife of turf and stone with the corrie on one side and the shoulder falling away on the other, and about two strides of level ground to do it on. Both drops are serious. The wind cannot decide which way it is going through here.', 0, 0, 'mountain', 0, 80, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-rim', 'north', 'the-north-corrie', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-rim', 'south', 'the-corrie-lip', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-upper-drift', 'door', 'The Upper Drift', 'Where the snowfield thins to a tongue and gives up, in a run of wet grit and old grey ice with stones sitting proud of it, each one in its own little melted cup. Everything on the surface here arrived from above and is waiting for the ice to let it down.', 0, 0, 'mountain', 0, 84, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-drift', 'north', 'the-melt-runnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-drift', 'west', 'the-old-snow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pass-head', 'door', 'The Pass Head', 'Out of the bealach and onto the shoulder proper, and the whole north side of the mountain arrives at once: a long bare rise going up to a level skyline, with nothing on it. No rock big enough to shelter behind, no dip, no cover of any kind. Anything up here can see you and you can see it.', 0, 0, 'mountain', 0, 78, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pass-head', 'east', 'the-shoulder-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pass-head', 'west', 'the-bealach', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shoulder-walk', 'door', 'The Shoulder Walk', 'The easy line along the shoulder, on ground cropped to nothing and firm as a road, which is the one gift this side of the mountain gives. It is also completely exposed for its entire length. Both of those are the same fact.', 0, 0, 'mountain', 0, 79, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-walk', 'south', 'the-shoulder-drop', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-walk', 'east', 'the-wind-scour', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-walk', 'west', 'the-pass-head', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wind-scour', 'door', 'The Wind Scour', 'The turf has been stripped off in a long patch, the way skin comes off, leaving bare gravel with the roots of what used to grow here still showing at the torn edges. The wind did this. It is still doing it, and the edge of the scour is a little further out every year.', 0, 0, 'mountain', 0, 80, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scour', 'north', 'the-wind-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scour', 'south', 'the-north-corrie', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scour', 'east', 'the-stone-stripes', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scour', 'west', 'the-shoulder-walk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stone-stripes', 'door', 'The Stone Stripes', 'The ground here has sorted itself into long parallel lines of stone running straight down the slope, with fine gravel between them, as regular as ploughing and going on for hundreds of yards. Frost did it, over a very long time, and it will keep doing it. There is no ploughman.', 0, 0, 'mountain', 0, 81, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-stripes', 'north', 'the-blown-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-stripes', 'south', 'the-snow-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-stripes', 'east', 'the-frost-shatter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-stripes', 'west', 'the-wind-scour', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-frost-shatter', 'door', 'The Frost Shatter', 'Rock broken into angular plates by nothing but water getting in and freezing, over and over, until the whole surface is a rubble of fragments still lying where they cracked apart. You can fit pieces back together with your hands. Nothing has moved them; they simply came to bits in place.', 0, 0, 'mountain', 0, 82, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-shatter', 'north', 'the-bare-plateau', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-shatter', 'south', 'the-cold-face', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-shatter', 'east', 'the-high-cairn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-shatter', 'west', 'the-stone-stripes', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-high-cairn', 'door', 'The High Cairn', 'The last cairn. Four courses of flat stone, the same as the ones down on the shoulder at the foot, set in the same careful way — and beyond it, in every direction, there is not another. Whoever built this line built it to here and then either turned back or did not need it any more. The stones are seated. It has not fallen in a very long time.', 0, 0, 'mountain', 0, 83, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-cairn', 'north', 'the-flat-top', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-cairn', 'south', 'the-plateau-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-cairn', 'west', 'the-frost-shatter', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shoulder-drop', 'door', 'The Shoulder Drop', 'The shoulder''s south edge, where the level ground ends and the whole side falls away into the corrie in one sweep of grass and scree. You can sit here with your legs over and see the lochan directly below, small and black and completely still. A ramp comes up onto the edge from the west, tilted and narrow, and it is not a thing you would notice from above.', 0, 0, 'mountain', 0, 79, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-drop', 'north', 'the-shoulder-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-drop', 'east', 'the-north-corrie', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-drop', 'west', 'the-slant', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-north-corrie', 'door', 'The North Corrie', 'A second, smaller bowl bitten out of the shoulder''s flank, holding nothing but shadow and a floor of wet stone. The sun reaches it for perhaps an hour in high summer. It is a cold place to walk through and a colder one to be in when the light goes off it.', 0, 0, 'mountain', 0, 80, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-corrie', 'north', 'the-wind-scour', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-corrie', 'south', 'the-corrie-rim', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-corrie', 'east', 'the-snow-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-corrie', 'west', 'the-shoulder-drop', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-snow-gully', 'door', 'The Snow Gully', 'A steep groove holding a tongue of hard old snow that runs a good way up the slope, blue-white and grooved down its length where meltwater has cut it. It is the fast way up if you have something to cut steps with and the fast way down if you do not.', 0, 0, 'mountain', 0, 81, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-gully', 'north', 'the-stone-stripes', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-gully', 'east', 'the-cold-face', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-gully', 'west', 'the-north-corrie', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cold-face', 'door', 'The Cold Face', 'North-facing rock, wet at all hours, with a black film on it that never dries and a fringe of ice at the top of every ledge for most of the year. Nothing grows on it but a rusty lichen that comes off on your palms. It is markedly colder here than fifty yards either side.', 0, 0, 'mountain', 0, 82, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-face', 'north', 'the-frost-shatter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-face', 'east', 'the-plateau-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-face', 'west', 'the-snow-gully', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-plateau-edge', 'door', 'The Plateau Edge', 'Where the shoulder''s top flattens out and stops being a slope at all, at a rim you can walk right up to without noticing you have arrived. Behind you the ground is level. In front of it there is a great deal of air and then the corrie floor.', 0, 0, 'mountain', 0, 83, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plateau-edge', 'north', 'the-high-cairn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plateau-edge', 'east', 'the-cold-shadow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plateau-edge', 'west', 'the-cold-face', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-flat-top', 'door', 'The Flat Top', 'Level ground, genuinely level, a plain of frost-shattered stone lying to the horizon with the sky sitting on it. There is no reference for distance up here and nothing to judge scale against, and something a hundred yards off and something a mile off look exactly alike.', 0, 0, 'mountain', 0, 83, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flat-top', 'south', 'the-high-cairn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flat-top', 'west', 'the-bare-plateau', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bare-plateau', 'door', 'The Bare Plateau', 'Stone pavement with a skin of gravel over it and about one plant to the square yard, each one flattened to a cushion and hard to the touch. This is what the top of the world is: not dramatic, just extremely poor. Everything here is small on purpose.', 0, 0, 'mountain', 0, 82, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-plateau', 'south', 'the-frost-shatter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-plateau', 'east', 'the-flat-top', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-plateau', 'west', 'the-blown-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-blown-ground', 'door', 'The Blown Ground', 'The gravel here has been sorted by wind rather than frost, into a rippled surface like the bottom of a stream, with the fine stuff gone entirely and only the pieces too heavy to lift left behind. There is no shelter within sight in any direction, and you can feel exactly how much that matters.', 0, 0, 'mountain', 0, 81, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blown-ground', 'south', 'the-stone-stripes', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blown-ground', 'east', 'the-bare-plateau', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blown-ground', 'west', 'the-wind-lane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wind-lane', 'door', 'The Wind Lane', 'A shallow trough across the plateau that the wind uses and has widened by using, so that the air in it moves visibly faster than the air on either side. Grit travels along it at ankle height in a continuous low stream. Standing across it is like standing in a river.', 0, 0, 'mountain', 0, 80, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-lane', 'south', 'the-wind-scour', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-lane', 'east', 'the-blown-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lower-band', 'door', 'The Lower Band', 'The face is built in horizontal bands — a wall of rock, a ledge of grass, a wall, a ledge — and this is the bottom one, a shelf a few strides wide running away east under an overhang. The ledges are the only walking there is on this side, and they do not connect where you want them to.', 0, 0, 'mountain', 0, 84, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-band', 'north', 'the-hanging-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-band', 'east', 'the-terrace', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-terrace', 'door', 'The Terrace', 'A wide grass ledge with the wall above and the wall below, level and green and improbably pleasant, going for two hundred yards and then simply stopping at a corner. Everything up here that eats grass comes to these, and everything that eats those knows it.', 0, 0, 'mountain', 0, 85, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace', 'north', 'the-ledge-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace', 'east', 'the-broken-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace', 'west', 'the-lower-band', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ledge-walk', 'door', 'The Ledge Walk', 'The ledge narrows to a foot''s width round a rib of rock, with a good hold at chest height for the six paces that matter and nothing at all below. It is not difficult. It is only difficult if you think about it, which is a distinction the mountain does not make and you will.', 0, 0, 'mountain', 0, 85, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ledge-walk', 'north', 'the-chimney-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ledge-walk', 'south', 'the-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ledge-walk', 'east', 'the-second-band', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-second-band', 'door', 'The Second Band', 'The next shelf up, drier and stonier than the one below it, with the wall behind it undercut enough to sit in out of the rain. There are droppings along the back of it in a line, all along, from something that walks this ledge regularly and rests in the same places every time.', 0, 0, 'mountain', 0, 86, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-band', 'north', 'the-chimney', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-band', 'south', 'the-broken-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-band', 'east', 'the-third-band', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-band', 'west', 'the-ledge-walk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-broken-terrace', 'door', 'The Broken Terrace', 'This shelf has come away in sections, so that what is left is a series of grass islands with gaps of steep bare rock between them, each gap a stride or a scramble. It was one continuous ledge once. You can see where it went, in a fan of turf and rubble on the ground far below.', 0, 0, 'mountain', 0, 86, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-terrace', 'north', 'the-second-band', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-terrace', 'east', 'the-slab-nose', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-terrace', 'west', 'the-terrace', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-chimney-foot', 'door', 'The Chimney Foot', 'The bottom of a vertical cleft splitting the wall from the ledge to the skyline, wide enough at the base to walk into and narrowing to a slot above. It is dark inside and there is a permanent trickle down the back of it. This is the way up through the bands and there is no other.', 0, 0, 'mountain', 0, 85, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney-foot', 'north', 'the-snow-bed', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney-foot', 'south', 'the-ledge-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney-foot', 'east', 'the-chimney', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-chimney', 'door', 'The Chimney', 'Inside the cleft: two walls a body''s width apart, wet, and holds enough to get up if you brace your back on one and your boots on the other. Somebody''s hands have polished the two obvious holds smooth. Somebody, at some point, more than once.', 0, 0, 'mountain', 0, 86, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney', 'south', 'the-second-band', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney', 'east', 'the-airy-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney', 'west', 'the-chimney-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-third-band', 'door', 'The Third Band', 'The highest of the shelves and the narrowest, with a great deal of nothing below it and the summit crags starting directly above. The grass on it is finer and shorter than the ledges below and there is very little of it. Everything up here is running out of everything.', 0, 0, 'mountain', 0, 87, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-band', 'north', 'the-airy-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-band', 'south', 'the-slab-nose', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-band', 'east', 'the-band-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-band', 'west', 'the-second-band', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-slab-nose', 'door', 'The Slab Nose', 'A prow of clean rock pushing out from the face where the bands run into it and stop, with the ledge dying away to nothing on either side. Round the front of it there is a step across a gap onto ground you cannot see until you are committed to it.', 0, 0, 'mountain', 0, 87, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slab-nose', 'north', 'the-third-band', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slab-nose', 'west', 'the-broken-terrace', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-airy-step', 'door', 'The Airy Step', 'Two strides on a ledge the width of a boot, with the wall pushing your shoulder out and six hundred feet under your heels, and good holds the whole way. It is genuinely safe and it does not feel remotely safe. Ravens use the ledge above and drop things off it, occasionally, on purpose.', 0, 0, 'mountain', 0, 87, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-airy-step', 'north', 'the-late-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-airy-step', 'south', 'the-third-band', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-airy-step', 'east', 'the-rake', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-airy-step', 'west', 'the-chimney', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-band-end', 'door', 'The Band End', 'The bands run out here against a buttress that cuts across them all, and the shelves simply end at it, one above another, like shelves in a broken cupboard. There is no way round at this level. Everything that comes along these ledges turns here, or goes up.', 0, 0, 'mountain', 0, 88, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-band-end', 'north', 'the-rake', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-band-end', 'west', 'the-third-band', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rake', 'door', 'The Rake', 'A long ramp of broken ground running diagonally up the face from the end of the bands, loose in places and grassy in others and always steeper than it looks from below. It is the mountain''s one concession on this side. It goes somewhere, which is more than the rest of this face does.', 0, 0, 'mountain', 0, 88, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake', 'south', 'the-band-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake', 'west', 'the-airy-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-snow-bed', 'door', 'The Snow Bed', 'A field of old snow lying in a hollow that faces away from every hour of sun there is, dirty on top, dense as packed sand underneath, and cold enough to feel from ten feet off. It has been getting a little smaller for a hundred years and it has not gone.', 0, 0, 'mountain', 0, 85, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-bed', 'north', 'the-moat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-bed', 'south', 'the-chimney-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-bed', 'east', 'the-firn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-bed', 'west', 'the-melt-runnel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-firn', 'door', 'The Firn', 'Snow gone halfway to ice: grainy, granular, so hard that it takes a heel to mark it, and blue where a crack goes down into it. Somewhere below this it stops being anything you could call snow. Nobody has ever needed to find out how far down that is.', 0, 0, 'mountain', 0, 86, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-firn', 'north', 'the-grey-ice', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-firn', 'east', 'the-late-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-firn', 'west', 'the-snow-bed', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-melt-runnel', 'door', 'The Melt Runnel', 'A channel cut into the snow itself by its own melting, waist deep and smooth-sided and running with clear water all day and nothing at all by first light. Follow it and it goes under the field and you cannot. The noise of water underneath carries for a good way.', 0, 0, 'mountain', 0, 84, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-runnel', 'north', 'the-cold-shadow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-runnel', 'south', 'the-upper-drift', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-runnel', 'east', 'the-snow-bed', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grey-ice', 'door', 'The Grey Ice', 'Not snow any more: a lens of grey bubbled ice standing proud of the slope, with grit frozen into it in layers you can count. Each dark line is a summer. There are more of them than seems reasonable and they get thinner toward the bottom.', 0, 0, 'mountain', 0, 86, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-ice', 'north', 'the-shattered-crown', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-ice', 'south', 'the-firn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-ice', 'east', 'the-white-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-ice', 'west', 'the-moat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-moat', 'door', 'The Moat', 'The gap between the snowfield and the rock behind it, where the warmth coming off the stone has melted a trench you could lose a horse in — vertical snow on one side, wet rock on the other, and no telling how deep the bottom is under the fallen stuff bridging it. You go round. Everything goes round.', 0, 0, 'mountain', 0, 85, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moat', 'north', 'the-snow-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moat', 'south', 'the-snow-bed', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moat', 'east', 'the-grey-ice', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moat', 'west', 'the-cold-shadow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cold-shadow', 'door', 'The Cold Shadow', 'Ground that has not had direct sun on it within living memory, walled to the south and floored with damp grey rubble and a moss that is nearly black. The temperature drops as you cross into it, sharply, in one step, and your breath shows.', 0, 0, 'mountain', 0, 84, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shadow', 'north', 'the-old-drift', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shadow', 'south', 'the-melt-runnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shadow', 'east', 'the-moat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shadow', 'west', 'the-plateau-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-drift', 'door', 'The Old Drift', 'A drift that formed in the lee of the crest and has been renewed every winter for so long that it has become a permanent feature of the mountain, with its own shape and its own edges and a hard scoured hollow in front of it. The wind builds it in the same place, the same way, every year.', 0, 0, 'mountain', 0, 84, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-drift', 'south', 'the-cold-shadow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-drift', 'east', 'the-snow-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-snow-edge', 'door', 'The Snow Edge', 'The lip where the drift breaks off, overhanging its own undercut face in a curl you could walk out onto without knowing it was there. It has broken before: there are blocks the size of carts lying below it, rounded and grey and slowly going.', 0, 0, 'mountain', 0, 85, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-edge', 'south', 'the-moat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-edge', 'east', 'the-shattered-crown', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-edge', 'west', 'the-old-drift', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shattered-crown', 'door', 'The Shattered Crown', 'The crest above the snow, a comb of rock split into standing plates by frost, leaning apart with gaps between them you can see the sky through. It looks deliberate from below, like something built and then ruined. It is neither.', 0, 0, 'mountain', 0, 86, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-crown', 'south', 'the-grey-ice', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-crown', 'west', 'the-snow-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-white-hollow', 'door', 'The White Hollow', 'A scoop of rock behind the ice with dry gravel in the bottom of it, sheltered from three sides and floored with a drift of small bones and old feathers a foot deep in places. Nothing here died today. Something has been carrying its dinner in here for a very, very long time.', 0, 1, 'mountain', 0, 87, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-hollow', 'south', 'the-late-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-hollow', 'west', 'the-grey-ice', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-late-field', 'door', 'The Late Field', 'The last of the snow, in a thin sheet holding on in the shade of the crest, going soft at the edges and undercut to a lace of white over black stone. In another month it will be gone. It will be back before it is properly gone.', 0, 0, 'mountain', 0, 87, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-late-field', 'north', 'the-white-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-late-field', 'south', 'the-airy-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-late-field', 'west', 'the-firn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sun-shoulder', 'door', 'The Sun Shoulder', 'Round the corner and everything changes: the wind drops, the rock is warm to the hand, and the ground goes from grey to brown and red. It is the same mountain and it is not the same mountain. All the living on this hill that can choose is on this side of it.', 0, 0, 'mountain', 0, 79, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-shoulder', 'east', 'the-heather-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-shoulder', 'west', 'the-south-shoulder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-heather-shelf', 'door', 'The Heather Shelf', 'Old heather, woody at the base and deep enough to hide anything lying down in it, growing on a broad terrace that runs along the flank at a comfortable angle for the first time since the shore. It smells of resin in the sun. Walking through it is loud and there is no way to make it not.', 0, 0, 'mountain', 0, 80, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-shelf', 'north', 'the-rowan', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-shelf', 'east', 'the-dry-corrie', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-shelf', 'west', 'the-sun-shoulder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dry-corrie', 'door', 'The Dry Corrie', 'A bowl the same shape as the one on the cold side and nothing at all like it: no water, no snow, a floor of dry grass and gravel, and the whole thing holding the afternoon heat like a wall. Things come here to lie up. You can see where, and the grass is still flat.', 0, 0, 'mountain', 0, 81, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-corrie', 'north', 'the-deer-lawn-high', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-corrie', 'south', 'the-hidden-burn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-corrie', 'east', 'the-warm-slabs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-corrie', 'west', 'the-heather-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-warm-slabs', 'door', 'The Warm Slabs', 'Tilted sheets of bare rock that take the sun all day and hold it well past dark, with the heat coming up off them in the evening and everything cold-blooded on this mountain arranged on them accordingly. Step carefully. Some of what is on the rock is exactly the colour of the rock.', 0, 0, 'mountain', 0, 82, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-slabs', 'north', 'the-wallow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-slabs', 'south', 'the-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-slabs', 'east', 'the-basking-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-slabs', 'west', 'the-dry-corrie', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-basking-stone', 'door', 'The Basking Stone', 'One flat boulder standing clear of the slope, worn shiny across the top of it, and warmer than the air by a noticeable margin from the moment the sun gets round to it. Something big lies on this. The wear on it is not weather.', 0, 0, 'mountain', 0, 83, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-stone', 'north', 'the-thin-turf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-stone', 'south', 'the-pothole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-stone', 'east', 'the-broken-ground-high', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-stone', 'west', 'the-warm-slabs', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-deer-lawn-high', 'door', 'The Deer Lawn', 'A patch of short bright green grass in the middle of the heather, kept that way by being eaten to the root every day for centuries. It is the best few hundred yards of grazing above the treeline and it is entirely surrounded by ground you cannot see through. Everything comes here. Everything knows everything comes here.', 0, 0, 'mountain', 0, 81, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-lawn-high', 'south', 'the-dry-corrie', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-lawn-high', 'east', 'the-wallow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-lawn-high', 'west', 'the-rowan', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wallow', 'door', 'The Wallow', 'A hollow of black peaty mud churned to soup and stinking, with the heather round it broken down and the mud thrown up the stems for a yard in every direction. Deer roll in this in the summer to get the flies off. It has been used this morning.', 0, 0, 'mountain', 0, 82, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wallow', 'south', 'the-warm-slabs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wallow', 'east', 'the-thin-turf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wallow', 'west', 'the-deer-lawn-high', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-thin-turf', 'door', 'The Thin Turf', 'Grass hanging on over rock with barely a finger of soil under it, so that whole sheets of it lift at the edges where feet have caught them and the rock shows through in patches like a worn coat. It is drying out. It has been drying out for a long time and it is nearly done.', 0, 0, 'mountain', 0, 83, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-turf', 'south', 'the-basking-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-turf', 'east', 'the-gravel-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-turf', 'west', 'the-wallow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rowan', 'door', 'The Rowan', 'One rowan tree growing out of a cleft in the rock, the only tree above the shore and by some distance the most improbable living thing on this mountain, with its roots gone down the crack and its head bent permanently downhill by the wind. Nothing planted it. A bird ate a berry somewhere lower and sat here, once, and that is the entire history of the only tree on this mountain.', 0, 0, 'mountain', 0, 80, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rowan', 'south', 'the-heather-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rowan', 'east', 'the-deer-lawn-high', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rowan', 'west', 'the-wedge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gravel-shelf', 'door', 'The Gravel Shelf', 'A wide terrace of loose sun-bleached gravel with almost nothing growing in it, hot underfoot by noon and completely bare of cover. Crossing it you are visible from the whole of the flank above, and there is no faster way across than walking.', 0, 0, 'mountain', 0, 84, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-shelf', 'south', 'the-broken-ground-high', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-shelf', 'east', 'the-hot-scree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-shelf', 'west', 'the-thin-turf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-broken-ground-high', 'door', 'The Broken Ground', 'Blocks and hollows and small cliffs three feet high, all through each other with no pattern, so that you are constantly stepping up or down and can never see more than twenty yards. It is exhausting and it is the best cover on this side of the hill, and those two facts are why things use it.', 0, 0, 'mountain', 0, 84, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-ground-high', 'north', 'the-gravel-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-ground-high', 'east', 'the-sun-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-ground-high', 'west', 'the-basking-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sun-gully', 'door', 'The Sun Gully', 'A dry gully running down the flank, floored with baked gravel and walled with warm rock, holding the heat like an oven and utterly still. Nothing moves in here in the middle of the day. Everything moves in here at dusk.', 0, 0, 'mountain', 0, 85, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-gully', 'north', 'the-hot-scree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-gully', 'east', 'the-resurgence', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-gully', 'west', 'the-broken-ground-high', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hot-scree', 'door', 'The Hot Scree', 'Scree on the sun side, pale and dry and shifting, with the heat coming off it in a shimmer that makes the ground above look like it is moving. It is hard to judge anything through that. Things standing still in it are very hard to see at all.', 0, 0, 'mountain', 0, 85, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-scree', 'south', 'the-sun-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-scree', 'west', 'the-gravel-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hidden-burn', 'door', 'The Hidden Burn', 'Water running under the heather rather than through it, audible the whole length of this hollow and visible almost nowhere, so that you walk along the sound of a stream you cannot find. Where it does show it is a hand''s width across and a foot deep and very fast.', 0, 0, 'mountain', 0, 81, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hidden-burn', 'north', 'the-dry-corrie', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hidden-burn', 'east', 'the-cut', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cut', 'door', 'The Cut', 'The burn has sawn itself a slot four feet deep and two wide in the solid rock, straight-sided, with the water at the bottom of it out of reach. You can stand astride it. Something has fallen in it further along — there is wool caught on the lip and a dark shape wedged below.', 0, 0, 'mountain', 0, 82, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut', 'north', 'the-warm-slabs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut', 'east', 'the-pothole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut', 'west', 'the-hidden-burn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pothole', 'door', 'The Pothole', 'A shaft in the bed of the cut, round and smooth and drilled straight down by a single stone turning in it for however long that takes, with the whole burn going into it and no sound of it landing. The stone that did the drilling is presumably still down there, still turning.', 0, 0, 'mountain', 0, 83, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pothole', 'north', 'the-basking-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pothole', 'east', 'the-sink', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pothole', 'west', 'the-cut', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sink', 'door', 'The Sink', 'The burn goes underground here, entirely, into a gap under a jammed boulder, and the streambed below it is dry gravel with dry weed lying combed along it. The change happens in one stride: water, then no water, and the noise going down and away under your feet.', 0, 0, 'mountain', 0, 84, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sink', 'east', 'the-dry-gorge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sink', 'west', 'the-pothole', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dry-gorge', 'door', 'The Dry Gorge', 'A gorge with no river in it: forty feet deep, walls scoured smooth and undercut, potholes drilled in the floor and dry to the bottom of them, and old flood-wrack jammed in the crevices well above your head. It is doing nothing at all today. It has done a great deal.', 0, 0, 'mountain', 0, 85, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-gorge', 'east', 'the-upper-force', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-gorge', 'west', 'the-sink', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-resurgence', 'door', 'The Resurgence', 'The water comes back out of the hill through a low arch, at pressure, cold enough to take your breath, having gone in half a mile back and a hundred feet higher. Nothing that goes into the sink has ever been seen to come out here. That is worth knowing before you decide the two are connected.', 0, 0, 'mountain', 0, 86, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-resurgence', 'south', 'the-upper-force', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-resurgence', 'east', 'the-boulder-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-resurgence', 'west', 'the-sun-gully', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-upper-force', 'door', 'The Upper Force', 'The reborn burn goes over a lip in a single fall into a bowl of its own making, and the noise fills the whole gorge and comes back off both walls. There is a permanent rainbow in the spray on a good afternoon and there is nothing up here to see it.', 0, 0, 'mountain', 0, 86, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-force', 'north', 'the-resurgence', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-force', 'east', 'the-water-notch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-force', 'west', 'the-dry-gorge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boulder-gate', 'door', 'The Boulder Gate', 'Two blocks the size of houses came down at some point and landed leaning against each other, and the gap under them is a doorway with a dry floor and a roof that has held for a very long time. Something has been sleeping in the back of it. There is no smell of anything recent.', 0, 1, 'mountain', 0, 87, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-gate', 'south', 'the-water-notch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-gate', 'east', 'the-mid-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-gate', 'west', 'the-resurgence', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-water-notch', 'door', 'The Water Notch', 'A slot the burn goes through where the gorge narrows to a stride, with the rock polished to a shine on both sides at chest height and everything below that scoured white. When it runs high this notch is the whole river and nobody is standing in it.', 0, 0, 'mountain', 0, 87, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-notch', 'north', 'the-boulder-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-notch', 'west', 'the-upper-force', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mid-shelf', 'door', 'The Mid Shelf', 'A broad shelf where the ground eases at last, with the gorge behind you and the ground above rearing back up into crags and snowfields you have not been near yet. It is a natural place to stop and it feels like one. Everything above this line is steeper than everything below it.', 0, 0, 'mountain', 0, 88, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-shelf', 'west', 'the-boulder-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-notch', 'east', 'the-slant', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cleft', 'east', 'the-wedge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-slant', 'door', 'The Slant', 'A ramp of turf and broken rock slanting up under the wall of the pass, wide enough to walk and too tilted to stand still on, with the whole weight of the crag leaning over it. Nothing made this and nothing maintains it. It is simply the one line across this face that does not require hands, and everything with four legs on this hill has known that for longer than there have been people to not know it.', 0, 0, 'mountain', 0, 78, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slant', 'east', 'the-shoulder-drop', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slant', 'west', 'the-wind-notch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wedge', 'door', 'The Wedge', 'A block the size of a cart jammed in the fissure at head height, and above it the crack goes on and lets you out on the shelf. Getting past the block is a squeeze with your back on one wall and your boots on the other, and there is nothing to hold on the way through. Something with a wide skull has been through here often enough to polish both sides.', 0, 0, 'mountain', 0, 79, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wedge', 'east', 'the-rowan', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wedge', 'west', 'the-cleft', NULL);
